const MaxBodyBytes = 65536

// Result is encoded as a single-field object, e.g. {"approvedIds":[...]}.
type Result struct {
	Field string
	IDs   []string
}

func (r Result) MarshalJSON() ([]byte, error) { return json.Marshal(map[string][]string{r.Field: r.IDs}) }

type Rejection struct{ Status int }

func (r *Rejection) Error() string { return fmt.Sprintf("action rejected: %d", r.Status) }

// Handler receives an authenticated approver, one valid Idempotency-Key and
// canonical (sorted, unique, 1..100) IDs.
type Handler func(context.Context, app.Identity, string, []string) (Result, bool, error)

// Routes maps an exact POST path to its Action handler.
type Routes map[string]Handler

// HTTP is the shared adapter for every batch Action endpoint; other requests
// go to the original server.
func HTTP(routes Routes, fallback http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		handle, found := routes[r.URL.Path]
		if r.Method != http.MethodPost || !found {
			fallback.ServeHTTP(w, r)
			return
		}
		u, ok := app.AuthenticateDemo(r.Header.Get("Authorization"))
		if !ok {
			reject(w, 401)
			return
		}
		if u.Role != "approver" {
			reject(w, 403)
			return
		}
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxBodyBytes))
		if err != nil {
			var large *http.MaxBytesError
			if errors.As(err, &large) {
				reject(w, 413)
			} else {
				reject(w, 400)
			}
			return
		}
		ids, ok := decode(body)
		keys := r.Header.Values("Idempotency-Key")
		if !ok || len(keys) != 1 || !validKey(keys[0]) {
			reject(w, 400)
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		defer cancel()
		result, replayed, err := handle(ctx, u, keys[0], ids)
		respond(w, result, replayed, err)
	})
}

// ItemResult is the response of a single-target Action: {"id":...,"status":...}.
type ItemResult struct {
	ID     string `json:"id"`
	Status string `json:"status"`
}

// ItemHandler receives an identity with the route's role, one valid
// Idempotency-Key, the path ID and the request reason.
type ItemHandler func(ctx context.Context, u app.Identity, key, id, reason string) (ItemResult, bool, error)

// Item serves POST /purchases/{id}/<verb> for one role. The body must be
// exactly {"reason":"..."} with 1..200 bytes of reason; other requests go to next.
func Item(verb, role string, handle ItemHandler, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id, found := strings.CutSuffix(strings.TrimPrefix(r.URL.Path, "/purchases/"), "/"+verb)
		if r.Method != http.MethodPost || !strings.HasPrefix(r.URL.Path, "/purchases/") || !found || id == "" || strings.Contains(id, "/") {
			next.ServeHTTP(w, r)
			return
		}
		u, ok := app.AuthenticateDemo(r.Header.Get("Authorization"))
		if !ok {
			reject(w, 401)
			return
		}
		if u.Role != role {
			reject(w, 403)
			return
		}
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxBodyBytes))
		if err != nil {
			var large *http.MaxBytesError
			if errors.As(err, &large) {
				reject(w, 413)
			} else {
				reject(w, 400)
			}
			return
		}
		reason, ok := decodeReason(body)
		keys := r.Header.Values("Idempotency-Key")
		if !ok || len(id) > 100 || !utf8.ValidString(id) || strings.ContainsRune(id, 0) || len(keys) != 1 || !validKey(keys[0]) {
			reject(w, 400)
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		defer cancel()
		result, replayed, err := handle(ctx, u, keys[0], id, reason)
		respond(w, result, replayed, err)
	})
}

// AssignResult is encoded as {"<Field>":[...],"assignee":...}.
type AssignResult struct {
	Field    string
	IDs      []string
	Assignee string
}

func (r AssignResult) MarshalJSON() ([]byte, error) {
	return json.Marshal(map[string]any{r.Field: r.IDs, "assignee": r.Assignee})
}

// AssignHandler receives an authenticated approver, one valid Idempotency-Key,
// canonical (sorted, unique, 1..100) IDs and the requested assignee user ID.
type AssignHandler func(ctx context.Context, u app.Identity, key string, ids []string, assignee string) (AssignResult, bool, error)

// Assign serves POST path for approvers. The body must be exactly
// {"ids":[...],"assignee":"..."} with a 1..100 byte assignee; other requests go to next.
func Assign(path string, handle AssignHandler, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != path {
			next.ServeHTTP(w, r)
			return
		}
		u, ok := app.AuthenticateDemo(r.Header.Get("Authorization"))
		if !ok {
			reject(w, 401)
			return
		}
		if u.Role != "approver" {
			reject(w, 403)
			return
		}
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxBodyBytes))
		if err != nil {
			var large *http.MaxBytesError
			if errors.As(err, &large) {
				reject(w, 413)
			} else {
				reject(w, 400)
			}
			return
		}
		ids, assignee, ok := decodeAssign(body)
		keys := r.Header.Values("Idempotency-Key")
		if !ok || len(keys) != 1 || !validKey(keys[0]) {
			reject(w, 400)
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
		defer cancel()
		result, replayed, err := handle(ctx, u, keys[0], ids, assignee)
		respond(w, result, replayed, err)
	})
}

func decodeAssign(body []byte) ([]string, string, bool) {
	if !utf8.Valid(body) {
		return nil, "", false
	}
	d := json.NewDecoder(bytes.NewReader(body))
	d.DisallowUnknownFields()
	var value struct {
		IDs      []string `json:"ids"`
		Assignee *string  `json:"assignee"`
	}
	if d.Decode(&value) != nil || d.Decode(new(any)) != io.EOF || value.IDs == nil || value.Assignee == nil {
		return nil, "", false
	}
	assignee := *value.Assignee
	if len(assignee) < 1 || len(assignee) > 100 || strings.ContainsRune(assignee, 0) {
		return nil, "", false
	}
	ids, err := canonical(value.IDs)
	return ids, assignee, err == nil
}

func respond(w http.ResponseWriter, result any, replayed bool, err error) {
	if err != nil {
		var rejected *Rejection
		var pg *pgconn.PgError
		switch {
		case errors.As(err, &rejected):
			reject(w, rejected.Status)
		case errors.As(err, &pg) && pg.Code == "23505":
			reject(w, 409)
		default:
			log.Printf("Action transaction failed: %v", err)
			reject(w, 503)
		}
		return
	}
	w.Header().Set("Content-Type", "application/json")
	if replayed {
		w.Header().Set("Idempotency-Replayed", "true")
	} else {
		w.Header().Set("Idempotency-Replayed", "false")
	}
	w.WriteHeader(200)
	_ = json.NewEncoder(w).Encode(result)
}

func decodeReason(body []byte) (string, bool) {
	if !utf8.Valid(body) {
		return "", false
	}
	d := json.NewDecoder(bytes.NewReader(body))
	d.DisallowUnknownFields()
	var value struct {
		Reason *string `json:"reason"`
	}
	if d.Decode(&value) != nil || d.Decode(new(any)) != io.EOF || value.Reason == nil {
		return "", false
	}
	reason := *value.Reason
	return reason, len(reason) >= 1 && len(reason) <= 200 && !strings.ContainsRune(reason, 0)
}

func reject(w http.ResponseWriter, status int) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]string{"error": http.StatusText(status)})
}

func decode(body []byte) ([]string, bool) {
	if !utf8.Valid(body) {
		return nil, false
	}
	d := json.NewDecoder(bytes.NewReader(body))
	if token, err := d.Token(); err != nil || token != json.Delim('{') {
		return nil, false
	}
	if key, err := d.Token(); err != nil || key != "ids" {
		return nil, false
	}
	var raw []json.RawMessage
	if d.Decode(&raw) != nil {
		return nil, false
	}
	if token, err := d.Token(); err != nil || token != json.Delim('}') {
		return nil, false
	}
	if d.Decode(new(any)) != io.EOF {
		return nil, false
	}
	ids := make([]string, len(raw))
	for i, value := range raw {
		if len(value) == 0 || value[0] != '"' || json.Unmarshal(value, &ids[i]) != nil {
			return nil, false
		}
	}
	ids, err := canonical(ids)
	return ids, err == nil
}

func canonical(ids []string) ([]string, error) {
	if len(ids) < 1 || len(ids) > 100 {
		return nil, &Rejection{400}
	}
	result := append([]string(nil), ids...)
	sort.Strings(result)
	for i, id := range result {
		if len(id) == 0 || len(id) > 100 || !utf8.ValidString(id) || (i > 0 && result[i-1] == id) {
			return nil, &Rejection{400}
		}
	}
	return result, nil
}

func validKey(key string) bool {
	if len(key) < 1 || len(key) > 128 {
		return false
	}
	for _, c := range key {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("._:-", c)) {
			return false
		}
	}
	return true
}
本版本在既有批量审批（POST /purchases/bulk-approve）、批量驳回（POST /purchases/bulk-reject）与重新提交（POST /purchases/{id}/reopen）的基础上，新增批量改派审批人：POST /purchases/bulk-reassign，请求体严格为 {"ids":[...],"assignee":"USER"}，ids 为 1..100 个不重复的采购单 ID，assignee 为 1..100 字节的用户 ID。只有已认证的 approver 可以调用。每个目标必须是当前租户中他人创建、状态为 submitted 的采购单；assignee 必须是当前租户 TenantMember 中 role 为 approver 且 active 的成员（可以是调用者本人）。成功后把全部目标的 Purchase.assigneeId 设为 assignee，status 及其他列都不变；任一目标不符合条件或 assignee 不合法时返回 4xx，数据库全部不变（全批原子）。请求体、身份、报文上限和 Idempotency-Key 校验由共享 HTTP 适配器 protocol.Assign 完成（路径 /purchases/bulk-reassign），新路径通过它注册。成功返回 200，响应为 {"reassignedIds":[按字典序排序的 ID],"assignee":USER}。首次成功 Idempotency-Replayed=false；同一 actor 以同一 key 重放同一请求（ID 集合与 assignee 都相同）时，返回相同状态和响应字节，header=true，不产生新写入；同 key 不同请求（ID 集合或 assignee 不同）返回 409。不同 actor 使用同名 key 互不影响。幂等结果与改派在同一事务中写入 ActionRequest：operation 为 "bulk-reassign.v6"，tenantId、actorId、key 分别为当前租户、当前用户和 Idempotency-Key 原值，response 为响应 JSON 对象，每个成功的新请求恰好一行。ActionRequest 写入失败时返回 503 且数据库全部不变，故障移除后同 key 可重试。并发：同 key 同请求两次均 200 且只提交一次；不同 key 把同一批采购单改派给不同 approver 时两次都 200，最终这些采购单的 assigneeId 都等于其中一个请求的 assignee。改派后的采购单仍可被批量审批、批量驳回，驳回后仍可被重新提交并再次改派。requester 调用返回 403，未认证返回 401；客户端上下文头不能覆盖认证身份。批量审批、批量驳回、重新提交与原有 API 行为保持不变。
package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

type Identity struct{ User, Tenant, Role string }

var identities = map[string]Identity{
	"demo_alice": {"alice", "tenant-a", "requester"},
	"demo_bob":   {"bob", "tenant-a", "approver"},
	"demo_carol": {"carol", "tenant-a", "approver"},
	"demo_dave":  {"dave", "tenant-b", "requester"},
	"demo_erin":  {"erin", "tenant-b", "approver"},
}

type Purchase struct {
	ID           string  `json:"id"`
	Tenant       string  `json:"tenantId"`
	Creator      string  `json:"createdBy"`
	Title        string  `json:"title"`
	Amount       int     `json:"amount"`
	Status       string  `json:"status"`
	InternalNote *string `json:"internalNote,omitempty"`
}
type Server struct {
	Pool     *pgxpool.Pool
	Guarded  bool
	Mutation string
}

const projection = `id,"tenantId","createdBy",title,amount,status`

func New(ctx context.Context, url, mode, mutation string) (*Server, error) {
	if mode != "baseline" && mode != "guarded" {
		return nil, fmt.Errorf("invalid mode")
	}
	if mutation != "" && os.Getenv("POC_ALLOW_MUTATIONS") != "1" {
		return nil, fmt.Errorf("fault injection requires POC_ALLOW_MUTATIONS=1")
	}
	if mutation != "" && mutation != "omit-tenant" && mutation != "skip-approval-check" && mutation != "leak-field" && mutation != "mass-assignment" && mutation != "bypass-action" {
		return nil, fmt.Errorf("unknown mutation")
	}
	pool, e := pgxpool.New(ctx, url)
	if e != nil {
		return nil, e
	}
	var unsafe bool
	e = pool.QueryRow(ctx, `SELECT rolsuper OR rolbypassrls OR pg_has_role(current_user, c.relowner, 'MEMBER') FROM pg_roles r CROSS JOIN pg_class c WHERE r.rolname=current_user AND c.oid='"Purchase"'::regclass`).Scan(&unsafe)
	if e != nil || unsafe {
		pool.Close()
		return nil, fmt.Errorf("runtime must use a non-owner, non-superuser, non-bypassrls role: %v", e)
	}
	if mode == "guarded" {
		var configured bool
		e = pool.QueryRow(ctx, `SELECT relrowsecurity AND relforcerowsecurity
          AND NOT has_column_privilege(current_user,c.oid,'internalNote','SELECT')
          AND NOT has_column_privilege(current_user,c.oid,'tenantId','UPDATE')
          AND NOT has_column_privilege(current_user,c.oid,'createdBy','UPDATE')
          AND (SELECT count(*)=3 FROM pg_policy p WHERE p.polrelid=c.oid)
          FROM pg_class c WHERE c.oid='"Purchase"'::regclass`).Scan(&configured)
		if e != nil || !configured {
			pool.Close()
			return nil, fmt.Errorf("guarded runtime requires configured RLS and column privileges: %v", e)
		}
	}
	return &Server{pool, mode == "guarded", mutation}, nil
}
func write(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
func deny(w http.ResponseWriter, status int) {
	write(w, status, map[string]string{"error": http.StatusText(status)})
}
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path == "/health" {
		if e := s.Pool.Ping(r.Context()); e != nil {
			deny(w, 503)
		} else {
			write(w, 200, map[string]bool{"ok": true})
		}
		return
	}
	user, ok := identities[strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")]
	if !ok || !strings.HasPrefix(r.Header.Get("Authorization"), "Bearer ") {
		deny(w, 401)
		return
	}
	if r.URL.Path != "/purchases" && !strings.HasPrefix(r.URL.Path, "/purchases/") {
		deny(w, 404)
		return
	}
	tx, e := s.Pool.Begin(r.Context())
	if e != nil {
		s.fail(w, e)
		return
	}
	defer tx.Rollback(r.Context())
	if s.Guarded {
